                            status?: "waiting" | "inprogress" | "finished";
                            /**
                             * Format: date-time
                             * @description RFC 3339 date indicating when the purge was completed. It can be empty if the purge is still in progress.
                             */
                            finishTime?: string;
                            /** @description Indicates the corresponding API request ID. */
                            apiRequestId: string;
                            /** @description ID of the API account used to create the purge request. This value is only set if the API account was created using our /ngadmin/apiAccounts <a href="#operation/post-ngadmin-apiAccounts">endpoint</a>. */
                            apiAccountId?: string;
                            /** @description Number of regex patterns that were part of the purge request. */
                            regexEntries?: number;
