                headers: {
                    [name: string]: unknown;
                };
                content: {
                    "application/json": {
                        /** @description Total number of service quota entries available. The number returned in serviceQuotaList may be fewer as it is limited to 200 entries. */
                        count: number;
                        /** @description A list of up to 200 service quota summaries. */
                        serviceQuotaList: {
                            /** @description A service quota ID. You can use this to <a href="#operation/get-cdn-serviceQuotas-serviceQuotaId">get more details about the service quota</a>. */
                            id: string;
                            /** @description ID of the customer. */
                            customerId: number;
                            /** @description Indicates the status of access to the CDN Pro product.  An <i>active</i> customer has full access. A <i>suspended</i> customer no longer has access. A <i>trial</i> customer is one with trial settings which may be more limited than those of a customer with the <i>active</i> status. */
                            status: string;
                            /** @description Indicates if deployment to production servers is permitted. Deployment to staging servers is always permitted. */
                            allowProduction: boolean;
                            /** @description A date in RFC 3339 format indicating when the trial expires. This field is required if the <i>status</i> field's value is <i>trial</i>. */
                            trialDeadline?: string;
                            /** @description This setting applies to trial customers. It is used to limit traffic use. It represents the number of days over which the traffic amount designated by the <i>usageLimitDollar</i> field can be used. For example, a value of 90 for <i>usageLimitDays</i> and 50 for <i>usageLimitDollar</i> means the customer can use up to $50 worth of total traffic over 90 day period. */
                            usageLimitDays?: number;
                            /** @description This setting applies to trial customers. It represents the amount of traffic valued in US dollars that is permitted to be used over a period of time  set by the <i>usageLimitDays</i> field. For example, a value of 90 for <i>usageLimitDays</i> and 50 for <i>usageLimitDollar</i> means the customer can use up to $50 worth of total traffic over 90 day period. The dollar value is based on CDN Pro's default pricing. */
                            usageLimitDollar?: number;
                            /**
                             * Format: date-time
                             * @description RFC 3339 date indicate when the service quota was created.
                             */
                            creationTime?: string;
                            /**
                             * Format: date-time
                             * @description RFC 3339 date indicating when the service quota was last updated.
                             */
                            lastUpdateTime?: string;
                        }[];
                    };
                };
